/**
 * PBR material library for the ambientCG surface kit staged in
 * `public/assets/textures/pbr/` (see `src/data/pbr_materials.json` and
 * `public/assets/textures/pbr/CREDITS.md`).
 *
 * The index is generated by the asset pipeline and is the single source of truth
 * for which maps exist. Everything here is lazy: nothing is fetched until a scene
 * asks for a slug, and each (slug, repeat) pair is cached for the session.
 *
 * Usage (Phase 4 room binding):
 *   const mat = await pbrMaterial('dungeon_slab', { repeat: 2 });
 *   mesh.material = mat;
 *
 * Note: `ao` maps need a second UV set (`geometry.setAttribute('uv2', uv)`), which
 * the procedural kit does not author yet. The map is still exposed so the binding
 * pass can opt in per mesh.
 */
import {
  MeshStandardMaterial,
  NoColorSpace,
  RepeatWrapping,
  SRGBColorSpace,
  TextureLoader,
  type Texture,
} from 'three';
import index from '../data/pbr_materials.json';

export type PbrMapKind = 'color' | 'normal' | 'roughness' | 'ao';
export type PbrRole = 'floor' | 'wall' | 'metal' | 'wood' | 'cloth' | 'roof' | 'ground';

export interface PbrMaterialEntry {
  assetId: string;
  displayName: string;
  role: PbrRole;
  /** World metres covered by one UV tile; drives `texture.repeat`. */
  metresCovered: number;
  note: string;
  sourceUrl: string;
  maps: Partial<Record<PbrMapKind, string>>;
  bytes: number;
}

export interface PbrIndex {
  version: number;
  source: string;
  license: string;
  mapScaleNote: string;
  materials: Record<string, PbrMaterialEntry>;
  hdr: Record<string, { assetId: string; displayName: string; note: string; sourceUrl: string; path: string; bytes: number }>;
}

export const PBR_INDEX = index as PbrIndex;
export const PBR_SLUGS = Object.keys(PBR_INDEX.materials);
export const PBR_NIGHT_SKY = PBR_INDEX.hdr.night_sky_moon;

/** Metalness per surface role. Everything else stays dielectric. */
const ROLE_METALNESS: Record<PbrRole, number> = {
  floor: 0.0,
  wall: 0.0,
  metal: 0.9,
  wood: 0.0,
  cloth: 0.0,
  roof: 0.0,
  ground: 0.0,
};

const sharedLoader = new TextureLoader();
const materialCache = new Map<string, MeshStandardMaterial>();
const textureCache = new Map<string, Texture>();

export interface PbrMaterialOptions {
  /** Multiplies the default repeat derived from `metresCovered`. */
  repeat?: number;
  /** sRGB tint applied on top of the color map. */
  tint?: number;
  /** Optional anisotropy for floors viewed at a grazing angle. */
  anisotropy?: number;
}

export function getPbrEntry(slug: string): PbrMaterialEntry {
  const entry = PBR_INDEX.materials[slug];
  if (!entry) {
    throw new Error(`[veilkeep] unknown PBR material "${slug}" (known: ${PBR_SLUGS.join(', ')})`);
  }
  return entry;
}

/** Synchronous assembly from already-decoded textures (used by tests and hot paths). */
export function buildPbrMaterial(
  slug: string,
  maps: Partial<Record<PbrMapKind, Texture>>,
  options: PbrMaterialOptions = {}
): MeshStandardMaterial {
  const entry = getPbrEntry(slug);
  const repeat = options.repeat ?? 1;

  const apply = (tex: Texture, srgb: boolean, anisotropy: number) => {
    tex.wrapS = RepeatWrapping;
    tex.wrapT = RepeatWrapping;
    tex.repeat.setScalar(repeat);
    tex.colorSpace = srgb ? SRGBColorSpace : NoColorSpace;
    tex.anisotropy = anisotropy;
    tex.needsUpdate = true;
    return tex;
  };

  const anisotropy = options.anisotropy ?? 4;
  const material = new MeshStandardMaterial({
    name: `VK_PBR_${slug}`,
    color: options.tint ?? 0xffffff,
    roughness: 1,
    metalness: ROLE_METALNESS[entry.role] ?? 0,
  });

  if (maps.color) material.map = apply(maps.color, true, anisotropy);
  if (maps.normal) material.normalMap = apply(maps.normal, false, anisotropy);
  if (maps.roughness) material.roughnessMap = apply(maps.roughness, false, anisotropy);
  if (maps.ao) material.aoMap = apply(maps.ao, false, anisotropy);
  material.userData.pbrSlug = slug;
  material.userData.metresCovered = entry.metresCovered;
  return material;
}

/**
 * Load (or reuse) a PBR material. Rejects if a map listed in the index is
 * missing on disk, so a broken export fails loudly at load time instead of
 * rendering an untextured room.
 */
export async function pbrMaterial(slug: string, options: PbrMaterialOptions = {}): Promise<MeshStandardMaterial> {
  const entry = getPbrEntry(slug);
  const key = `${slug}|${options.repeat ?? 1}|${options.tint ?? 0xffffff}|${options.anisotropy ?? 4}`;
  const cached = materialCache.get(key);
  if (cached) return cached;

  const maps: Partial<Record<PbrMapKind, Texture>> = {};
  await Promise.all(
    (Object.entries(entry.maps) as Array<[PbrMapKind, string]>).map(async ([kind, url]) => {
      const texKey = `${slug}|${kind}`;
      let tex = textureCache.get(texKey);
      if (!tex) {
        tex = await sharedLoader.loadAsync(url);
        textureCache.set(texKey, tex);
      }
      maps[kind] = tex;
    })
  );

  const material = buildPbrMaterial(slug, maps, options);
  materialCache.set(key, material);
  return material;
}

/** Release every material and texture this library created. */
export function disposePbrCache(): void {
  for (const material of materialCache.values()) material.dispose();
  for (const texture of textureCache.values()) texture.dispose();
  materialCache.clear();
  textureCache.clear();
}
